# ============================================================
# CROPCARE AI — AUTOMATED PDF ADVISORY REPORT GENERATOR
# ============================================================
# Generates professional, publication-quality agricultural PDF
# reports using ReportLab, combining:
#   1. Vision model diagnosis (Crop, Disease, Confidence, Severity)
#   2. High-resolution thumbnail of the inspected leaf photo
#   3. Comprehensive farmer treatment guide generated by Gemini
#   4. Page references from the official Master Guide PDF
# ============================================================

import io
import re
import html
from datetime import datetime
from typing import Dict, Any, List, Optional
from PIL import Image

from reportlab.lib.pagesizes import letter
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.platypus import (
    SimpleDocTemplate,
    Paragraph,
    Spacer,
    Table,
    TableStyle,
    Image as RLImage,
    HRFlowable
)


def _convert_markdown_to_flowables(md_text: str, styles: Dict[str, ParagraphStyle]) -> List[Any]:
    """
    Parses Markdown headings, bold text, and bullet points into
    ReportLab Flowables safely.
    """
    flowables = []
    lines = md_text.strip().split("\n")

    for line in lines:
        raw_line = line.strip()
        if not raw_line:
            flowables.append(Spacer(1, 5))
            continue

        # Headings
        if raw_line.startswith("### "):
            text = html.escape(raw_line[4:])
            text = re.sub(r"\*\*(.*?)\*\*", r"<b>\1</b>", text)
            flowables.append(Spacer(1, 6))
            flowables.append(Paragraph(f"<b>{text}</b>", styles["SectionH3"]))
            flowables.append(Spacer(1, 3))
        elif raw_line.startswith("## "):
            text = html.escape(raw_line[3:])
            text = re.sub(r"\*\*(.*?)\*\*", r"<b>\1</b>", text)
            flowables.append(Spacer(1, 8))
            flowables.append(Paragraph(f"<b>{text}</b>", styles["SectionH2"]))
            flowables.append(Spacer(1, 4))
        elif raw_line.startswith("# "):
            text = html.escape(raw_line[2:])
            text = re.sub(r"\*\*(.*?)\*\*", r"<b>\1</b>", text)
            flowables.append(Spacer(1, 10))
            flowables.append(Paragraph(f"<b>{text}</b>", styles["SectionH1"]))
            flowables.append(Spacer(1, 5))
        elif raw_line.startswith("- ") or raw_line.startswith("* "):
            text = html.escape(raw_line[2:])
            text = re.sub(r"\*\*(.*?)\*\*", r"<b>\1</b>", text)
            flowables.append(Paragraph(f"&bull;&nbsp;&nbsp;{text}", styles["BulletText"]))
            flowables.append(Spacer(1, 3))
        elif re.match(r"^\d+\.\s", raw_line):
            match = re.match(r"^(\d+\.)\s*(.*)", raw_line)
            num_prefix = match.group(1)
            content = html.escape(match.group(2))
            content = re.sub(r"\*\*(.*?)\*\*", r"<b>\1</b>", content)
            flowables.append(Paragraph(f"<b>{num_prefix}</b> {content}", styles["BulletText"]))
            flowables.append(Spacer(1, 3))
        else:
            text = html.escape(raw_line)
            text = re.sub(r"\*\*(.*?)\*\*", r"<b>\1</b>", text)
            flowables.append(Paragraph(text, styles["Body"]))
            flowables.append(Spacer(1, 4))

    return flowables


def generate_disease_advisory_pdf(
    diagnosis: Dict[str, Any],
    advisory_text: str,
    sources: Optional[List[Dict[str, Any]]] = None,
    leaf_image: Optional[Image.Image] = None
) -> bytes:
    """
    Builds a complete, formatted PDF advisory report.

    Args:
        diagnosis: Output from CropVisionPipeline.predict_disease()
        advisory_text: Comprehensive guide generated by Gemini RAG chatbot
        sources: List of source page references from Master Guide
        leaf_image: PIL Image of the inspected leaf

    Returns:
        bytes: Raw PDF file bytes ready for download
    """
    buffer = io.BytesIO()

    # Document setup with 0.5 in margins for maximum readable layout
    doc = SimpleDocTemplate(
        buffer,
        pagesize=letter,
        leftMargin=36,
        rightMargin=36,
        topMargin=36,
        bottomMargin=36
    )

    # ── Custom Styles ──────────────────────────────────────────
    base_styles = getSampleStyleSheet()

    styles = {
        "ReportTitle": ParagraphStyle(
            "ReportTitle",
            parent=base_styles["Title"],
            fontSize=20,
            leading=24,
            textColor=colors.HexColor("#1B5E20"),
            fontName="Helvetica-Bold",
            alignment=0,
            spaceAfter=2
        ),
        "ReportSubtitle": ParagraphStyle(
            "ReportSubtitle",
            fontSize=10,
            leading=13,
            textColor=colors.HexColor("#4B5563"),
            fontName="Helvetica",
            spaceAfter=10
        ),
        "SectionH1": ParagraphStyle(
            "SectionH1",
            fontSize=13,
            leading=16,
            textColor=colors.HexColor("#1B5E20"),
            fontName="Helvetica-Bold",
            spaceBefore=10,
            spaceAfter=4
        ),
        "SectionH2": ParagraphStyle(
            "SectionH2",
            fontSize=11,
            leading=14,
            textColor=colors.HexColor("#2E7D32"),
            fontName="Helvetica-Bold",
            spaceBefore=8,
            spaceAfter=3
        ),
        "SectionH3": ParagraphStyle(
            "SectionH3",
            fontSize=10,
            leading=13,
            textColor=colors.HexColor("#111827"),
            fontName="Helvetica-Bold",
            spaceBefore=6,
            spaceAfter=2
        ),
        "Body": ParagraphStyle(
            "Body",
            fontSize=9.5,
            leading=13,
            textColor=colors.HexColor("#1F2937"),
            fontName="Helvetica"
        ),
        "BulletText": ParagraphStyle(
            "BulletText",
            fontSize=9.5,
            leading=13,
            textColor=colors.HexColor("#1F2937"),
            fontName="Helvetica",
            leftIndent=12
        ),
        "MetaLabel": ParagraphStyle(
            "MetaLabel",
            fontSize=9,
            leading=12,
            textColor=colors.HexColor("#6B7280"),
            fontName="Helvetica-Bold"
        ),
        "Disclaimer": ParagraphStyle(
            "Disclaimer",
            fontSize=8,
            leading=11,
            textColor=colors.HexColor("#6B7280"),
            fontName="Helvetica-Oblique",
            alignment=1
        )
    }

    story = []

    # ── Top Header Banner ───────────────────────────────────────
    story.append(Paragraph("🌿 CropCare AI — Plant Pathology & Farmer Advisory Report", styles["ReportTitle"]))
    story.append(Paragraph(
        f"Automated Health Assessment & Master Guide Recommendations &bull; Generated: {datetime.now().strftime('%d %B %Y, %I:%M %p')}",
        styles["ReportSubtitle"]
    ))
    story.append(HRFlowable(width="100%", thickness=1.5, color=colors.HexColor("#2E7D32"), spaceAfter=10))

    # ── Summary Metadata Table with Leaf Thumbnail ──────────────
    crop = diagnosis.get("crop", "Tomato/Potato")
    disease = diagnosis.get("disease_name", "Early Blight")
    scientific = diagnosis.get("scientific_name", "")
    severity = diagnosis.get("severity", "Moderate")
    confidence = diagnosis.get("confidence", 95.0)

    # Color for severity badge
    sev_color_hex = diagnosis.get("severity_color", "#E65100")

    meta_text = f"""
    <b>Crop:</b> {crop}<br/>
    <b>Diagnosed Condition:</b> <font color="{sev_color_hex}"><b>{disease}</b></font><br/>
    <b>Scientific Name:</b> <i>{scientific}</i><br/>
    <b>Model Confidence:</b> <b>{confidence}%</b><br/>
    <b>Severity Level:</b> <b>{severity}</b><br/>
    <b>Inspection Status:</b> Verified Leaf Foliage
    """

    meta_cell = Paragraph(meta_text, styles["Body"])

    # Image thumbnail cell
    img_cell = Paragraph("<i>No Image Provided</i>", styles["Body"])
    if leaf_image is not None:
        try:
            # Resize image to thumbnail
            thumb = leaf_image.copy().convert("RGB")
            thumb.thumbnail((180, 140))
            img_buf = io.BytesIO()
            thumb.save(img_buf, format="JPEG", quality=85)
            img_buf.seek(0)
            img_cell = RLImage(img_buf, width=150, height=115)
        except Exception:
            pass

    table_data = [
        [
            Paragraph("<b>Diagnosis Details</b>", styles["SectionH3"]),
            Paragraph("<b>Inspected Foliage</b>", styles["SectionH3"])
        ],
        [meta_cell, img_cell]
    ]

    meta_table = Table(table_data, colWidths=[360, 180])
    meta_table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor("#F8FAF8")),
        ("BOX", (0, 0), (-1, -1), 1, colors.HexColor("#D1E7D7")),
        ("INNERGRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#E5E7EB")),
        ("TOPPADDING", (0, 0), (-1, -1), 8),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 8),
        ("LEFTPADDING", (0, 0), (-1, -1), 10),
        ("RIGHTPADDING", (0, 0), (-1, -1), 10),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
    ]))

    story.append(meta_table)
    story.append(Spacer(1, 14))

    # ── Executive Summary Paragraph ────────────────────────────
    summary_text = diagnosis.get("summary", "")
    if summary_text:
        story.append(Paragraph("<b>Executive Diagnostic Summary:</b>", styles["SectionH2"]))
        story.append(Paragraph(summary_text, styles["Body"]))
        story.append(Spacer(1, 8))

    # ── Chatbot Comprehensive Advisory Section ─────────────────
    story.append(Paragraph("<b>Comprehensive Master Guide Advisory:</b>", styles["SectionH1"]))
    story.append(HRFlowable(width="100%", thickness=0.8, color=colors.HexColor("#A7F3D0"), spaceAfter=6))

    # Convert advisory markdown into Flowables
    advisory_flowables = _convert_markdown_to_flowables(advisory_text, styles)
    story.extend(advisory_flowables)
    story.append(Spacer(1, 10))

    # ── Official Master Guide Sources Table ────────────────────
    if sources:
        story.append(Spacer(1, 6))
        story.append(Paragraph("<b>Official Master Guide Citations:</b>", styles["SectionH2"]))
        
        sources_rows = [[Paragraph("<b>Page</b>", styles["SectionH3"]), Paragraph("<b>Guide Reference Excerpt</b>", styles["SectionH3"])]]
        for src in sources[:4]:  # Show top 4 citations
            page_str = f"Page {src.get('page', '?')}"
            content_str = html.escape(src.get('content', '')[:180]) + "..."
            sources_rows.append([
                Paragraph(f"<b>{page_str}</b>", styles["MetaLabel"]),
                Paragraph(f"<i>&ldquo;{content_str}&rdquo;</i>", styles["Body"])
            ])

        src_table = Table(sources_rows, colWidths=[70, 470])
        src_table.setStyle(TableStyle([
            ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E8F5E9")),
            ("BACKGROUND", (0, 1), (-1, -1), colors.HexColor("#FAFAFA")),
            ("BOX", (0, 0), (-1, -1), 0.8, colors.HexColor("#C8E6C9")),
            ("INNERGRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#E5E7EB")),
            ("TOPPADDING", (0, 0), (-1, -1), 5),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
            ("LEFTPADDING", (0, 0), (-1, -1), 8),
            ("RIGHTPADDING", (0, 0), (-1, -1), 8),
        ]))
        story.append(src_table)
        story.append(Spacer(1, 14))

    # ── Footer / Disclaimer ─────────────────────────────────────
    story.append(HRFlowable(width="100%", thickness=0.5, color=colors.HexColor("#9CA3AF"), spaceAfter=6))
    story.append(Paragraph(
        "Notice: This report was automatically prepared by CropCare AI using deep learning vision and the Tomato & Potato Farmer Master Guide. "
        "It provides grounded recommendations and cultural practices. For chemical application approvals or severe regional disease spread, "
        "please consult your local Krishi Vigyan Kendra (KVK) or district agricultural extension officer.",
        styles["Disclaimer"]
    ))

    # Build PDF
    doc.build(story)
    pdf_bytes = buffer.getvalue()
    buffer.close()
    return pdf_bytes
